'use strict';
const $=s=>document.querySelector(s);
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let savedTheme;try{savedTheme=localStorage.getItem('danny-theme')}catch{}
function theme(value){document.documentElement.dataset.theme=value;$('.theme-button').textContent=value==='dark'?'☼':'◐';$('.theme-button').setAttribute('aria-label',value==='dark'?'切換淺色模式':'切換深色模式');try{localStorage.setItem('danny-theme',value)}catch{}}
theme(savedTheme==='light'?'light':'dark');$('.theme-button').onclick=()=>theme(document.documentElement.dataset.theme==='dark'?'light':'dark');
function clock(){ $('#local-time').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' UTC+8'}clock();setInterval(clock,30000);
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',String(t===b))});let count=0;document.querySelectorAll('.project').forEach(p=>{p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter;if(!p.hidden)count++});$('.filter-count').textContent='SHOWING '+String(count).padStart(2,'0')+' PROJECTS'});
const entries={
ttt:{title:'TTT / 讓模型在單卡上持續探索',body:`<p>一個問題的起點：只有一張 RTX 4090，如何讓模型生成想法、產出程式、接受評估，再接續更新？</p><h3>先處理重複載入</h3><p>生成與訓練原本各自載入模型。我將交替執行的階段改為共享同一份 base model 與 LoRA adapter，並以本地 Qwen2.5-Coder-7B-Instruct 取代外部產碼流程。搜尋、reward 與時間驗證沿用既有框架。</p><p class="detail-metric">18.82 → 13.63 GiB</p><p class="detail-small">4-bit 組態下的 PyTorch allocated memory 峰值比較，減少 5.19 GiB。此數值不是 GPU 整體占用。</p><h3>再縮短候選的等待</h3><p>固定 16 個 idea，在 vLLM 上比較併發 1、4、8、16，每組重複三次。產碼、驗證與評分的整批時間中位數，從 39.52 秒降至 5.34 秒，約加速 7.4 倍。</p><p>這是同一個推論引擎內的併發比較，不是 vLLM 對其他引擎的比較。計時不含 idea 生成和 LoRA 更新，也不代表完整 TTT 流程的加速倍率。</p><h3>快速之外，保留檢查</h3><p>每批有 7～8 個候選通過檢查且沒有退化。生成速度與候選品質是不同的問題，需要分別驗證。這個研究仍持續探索模型實作、資源配置與實驗流程之間的關係。</p>`},
agent:{title:'企業 AI Agent / 把模型接進工作流程',body:`<p>讓使用者描述需求，由模型撰寫 SQL，透過 MCP 資料庫工具執行，再根據實際查詢結果整理回覆。</p><h3>我的工作</h3><p>獨立完成架構設計、MCP 工具、資料整合與正式上線。模型推論使用閉源服務，工具端提供安全的資料庫操作。</p><h3>從對話到執行</h3><p>這個專案的重點，是把模型的回答接到真實資料與可執行工具。工程工作包含釐清資料需求、設計工具介面，以及讓各個部分在實際流程中連接起來。</p><p>它和個人的 TTT 模型研究是獨立專案。這裡展示的是系統思路，未包含公司資料、內部程式碼或部署設定。</p>`},
worldquant:{title:'WorldQuant / 讓研究可以接續',body:`<p class="detail-metric">2026 · 台灣區第四名</p><p>在 BRAIN 平台上使用 Agent 推動因子探索，將研究假說、具體實作與回測結果連成可以追溯的流程。</p><h3>研究樹</h3><p>每個研究節點記錄它從哪個方向延伸、改了哪些參數，以及改動背後的理由。相同想法的不同實作分開保存，失敗和篩選結果也留下紀錄。</p><h3>從結果決定下一步</h3><p>候選完成回測後，將績效與檢查結果寫回紀錄，再依結果選擇值得延伸的分支。這個系統使用 Agent 與工具串接，不等同於 TTT 的模型訓練閉環。</p><p>回測結果用於研究比較，不代表實際投資收益。</p>`},
wafer:{title:'Wafer Map / 回到數值本身',body:`<p>自動攔檢需要同時考慮該攔下的異常，以及不應誤攔的正常情況。我的工作從量測資料的表示方式開始。</p><h3>重新檢查影像表示</h3><p>原始資料是數值型。如果先轉成圖片，就需要選擇顏色、尺度與轉換規則。當時沒有找到能公平保留原始特徵的方式，因此我回到數值特徵與製程知識，建立判讀流程。</p><h3>已落地與持續研究</h3><p>既有方案結合統計特徵與製程規則。目前持續研究隨機森林，在特徵工程與實驗之間調整，希望進一步提升判讀準確度。</p><p>網站的晶圓視覺為抽象圖形，不是實際產線資料。</p>`},
stdf:{title:'STDF / 讓新系統正確接手',body:`<p>以 Python 開源轉檔方案為基礎，客製化擷取所需欄位，再使用 Cython 改善大量資料的處理效能。</p><h3>看起來缺失，不一定真的缺失</h3><p>新舊系統比對時，一個沒有數值的欄位，可能代表缺失，也可能是量測故障。需要交叉檢查相關欄位與狀態 flag，才能確認真正的意思。</p><h3>把驗證放進交付</h3><p>在確認輸出差異與資料語意後，讓替代系統接手既有流程。截至這次專案整理，系統已上線半年，尚未需要修改或進版。</p><p>這個專案讓我學到，轉出資料只是第一步，後續系統能正確理解資料，才是完成交付。</p>`},
batch:{title:'併發增加，為什麼不會等比例變快？',body:`<p>同樣一批 16 個 idea，逐一處理用了 39.52 秒，併發 16 則是 5.34 秒。這讓等待時間明顯縮短，但沒有變成十六分之一。</p><h3>請求增加，硬體沒有增加</h3><p>所有請求仍共用同一張 GPU。批次處理有機會讓硬體更有效率地工作，但大家也同時分享算力和記憶體頻寬。</p><h3>等的是整批最後一個結果</h3><p>不同請求生成的程式長度不同；同一份回答也仍需逐步生成。除了產碼，整批計時還包含驗證、評分及初始化等工作。</p><h3>這次量到了什麼？</h3><p>併發 1、4、8、16 的完成時間中位數，分別為 39.52、11.76、7.95、5.34 秒。這證實了此工作負載的批次收益，但要定位算力、頻寬或排程的主要限制，仍需要額外 profiling。</p><p class="detail-small">2026-09-10 固定候選實驗整理。各組三次；使用相同 vLLM 引擎。未計入 idea 生成與模型訓練。</p>`},
representation:{title:'在選模型之前，先想想資料長什麼樣。',body:`<p>影像模型很有吸引力，但當手上的原始資料是數值，把它轉成圖片本身就是一連串設計決策。</p><h3>表示方式會影響看見的訊號</h3><p>顏色如何對應數值？尺度如何設定？數值之間的差異，轉換後還保留了多少？如果沒有先處理這些問題，模型學到的可能也包含轉換方式帶入的痕跡。</p><h3>從問題回到資料</h3><p>在 Wafer Map 專案中，我選擇回到數值特徵，結合製程知識與規則來設計判讀。這不表示影像方法一定不適合，而是當時需要先建立更合理的資料表示與驗證方式。</p><p>對我來說，選模型之前，先弄清楚模型實際看見什麼，是值得花時間的一步。</p>`},
trace:{title:'失敗的實驗，也值得留下一個位置。',body:`<p>當實驗越做越多，只記得「這個分數很好」還不夠。我更想知道，它為什麼變好，和上一版到底差在哪裡。</p><h3>把改動理由一起保存</h3><p>在 WorldQuant 的研究流程中，我將假說、實作與回測分開記錄，並保留父節點和延伸分支的關係。同一想法的不同參數組合，也能各自追溯。</p><h3>被淘汰的結果也是線索</h3><p>如果只保存成功的實驗，就很容易重走已經試過的路。記錄失敗、限制與篩選原因，可以讓下一次研究更清楚地知道要改什麼。</p><p>自動化不只是多跑幾次，也包括讓每次執行留下可以理解、可以接續的紀錄。</p>`}
};
let lastFocus=null;const dialog=$('#detail');function openEntry(key,kind){const e=entries[key];if(!e)return;lastFocus=document.activeElement;$('#detail-title').textContent=e.title;$('#detail-kind').textContent=kind;$('#detail-content').innerHTML=e.body;dialog.showModal();dialog.scrollTop=0;document.body.classList.add('modal-open');$('#close-detail').focus()}
document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>openEntry(b.dataset.project,'PROJECT FILE / '+b.dataset.project.toUpperCase()));document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>openEntry(b.dataset.note,'FIELD NOTE / RESEARCH'));
$('#close-detail').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastFocus?.focus()});
$('#copy-email').onclick=async()=>{try{await navigator.clipboard.writeText('pangyenwang@gmail.com');$('#copy-status').textContent='已複製，期待你的來信。'}catch{$('#copy-status').textContent='請選取並複製：pangyenwang@gmail.com'}};
const canvas=$('#field'),ctx=canvas.getContext('2d');let width=0,height=0,angle=.4,last=0,paused=reduced.matches,visible=true,form='torus',px=0,py=0;
function size(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);render()}
function render(){ctx.clearRect(0,0,width,height);const light=document.documentElement.dataset.theme==='light';const points=[];for(let i=0;i<65;i++)for(let j=0;j<24;j++){const u=i/65*Math.PI*2,v=j/24*Math.PI*2;let x,y,z;if(form==='torus'){x=(1+.38*Math.cos(v))*Math.cos(u);y=(1+.38*Math.cos(v))*Math.sin(u);z=.38*Math.sin(v)}else{x=Math.sin(v)*Math.cos(u)*1.2;y=Math.cos(v)*1.2;z=Math.sin(v)*Math.sin(u)*1.2}const a=angle+px*.35,b=.75+py*.3;const x1=x*Math.cos(a)-z*Math.sin(a),z1=x*Math.sin(a)+z*Math.cos(a),y1=y*Math.cos(b)-z1*Math.sin(b),z2=y*Math.sin(b)+z1*Math.cos(b);points.push([x1,y1,z2])}points.sort((a,b)=>a[2]-b[2]);const scale=Math.min(width/3.6,height/3.6);ctx.font='11px Consolas, monospace';ctx.textAlign='center';for(const [x,y,z] of points){const f=3.8/(3.8-z);ctx.globalAlpha=.16+(z+1.5)/3*.8;ctx.fillStyle=light?'#406d15':'#c5f776';ctx.fillText(z>.6?'#':z>0?'+':'.',width/2+x*scale*f,height/2+y*scale*f)}ctx.globalAlpha=1}
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();px=(e.clientX-r.left)/width-.5;py=(e.clientY-r.top)/height-.5;if(paused)render()});canvas.addEventListener('pointerleave',()=>{px=0;py=0;if(paused)render()});$('#shape').onclick=()=>{form=form==='torus'?'sphere':'torus';$('#form-name').textContent=form==='torus'?'TORUS FIELD':'SPHERE FIELD';render()};function motionLabel(){$('#motion').textContent=paused?'▷':'Ⅱ';$('#motion').setAttribute('aria-label',paused?'播放動畫':'暫停動畫')}motionLabel();$('#motion').onclick=()=>{paused=!paused;motionLabel()};new ResizeObserver(size).observe(canvas);new IntersectionObserver(es=>visible=es[0].isIntersecting).observe(canvas);new MutationObserver(render).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});reduced.addEventListener('change',e=>{paused=e.matches;motionLabel()});function animate(now){if(!paused&&visible&&!document.hidden&&now-last>45){angle+=.008;render();last=now}requestAnimationFrame(animate)}requestAnimationFrame(animate);
